<div class="container storefront"><section class="profile-panel"><h1>Đơn hàng của tôi</h1><?php if($orders): ?><table class="order-table"><thead><tr><th>Mã đơn</th><th>Ngày</th><th>Tổng</th><th>Trạng thái</th><th>TT</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><a href="<?= BASE_URL ?>?action=order-detail&id=<?= e($o['id']) ?>"><?= e($o['order_code']) ?></a></td><td><?= e($o['created_at']) ?></td><td><?= number_format($o['total_amount'],0,',','.') ?>đ</td><td><?= e($o['status']) ?></td><td><?= e(strtoupper($o['payment_method'])) ?></td></tr><?php endforeach; ?></tbody></table><?php else: ?><p>Chưa có đơn hàng.</p><?php endif; ?></section></div>
